def distribute_elements(nums):
    # Handle edge cases for length < 2
    if not nums:
        return []
    if len(nums) == 1:
        return nums.copy()

    arr1 = [nums[0]]
    arr2 = [nums[1]]

    for i in range(2, len(nums)):
        # Compare last elements
        if arr1[-1] > arr2[-1]:
            arr1.append(nums[i])
        else:
            arr2.append(nums[i])
    # Concatenate arr1 and arr2
    return arr1 + arr2
